import React, { useState, useEffect, useRef } from 'react';
import DropDown from '../forms/DropDown';
import AddProjectInterface from './AddProjectInterface';
import TrackJournal from './TrackJournal';
import { currentTime, currentDate } from '../utils/CurrentCalendar';
import initProjects from './initProjects';
import trackables from './trackables';
import initJournalTracking from './initJournalTracking';
import CollapseToggleButton from '../utils/CollapseToggleButton';
import getKey from '../utils/KeyGenerator';
import initializeData from '../utils/InitializeData';

const Journals = () => {
    const [projects, setProjects] = useState(() => initializeData('projects', initProjects));
    const [journals, setJournals] = useState(() => initializeData('journalTracking', initJournalTracking));
    const [tracking, setTracking] = useState('journals');
    const [isCollapsed, setIsCollapsed] = useState(false);
    const [newProjectDescription, setNewProjectDescription] = useState('');
    const [currentGoalsCollapse, setCurrentGoalsCollapse] = useState(true);
    const [futureGoalsCollapse, setFutureGoalsCollapse] = useState(true);
    const [completedGoalsCollapse, setCompletedGoalsCollapse] = useState(true);

    const targetElementRef = useRef(null);

    // Persist projects and journals
    useEffect(() => {
        localStorage.setItem('projects', JSON.stringify(projects));
    }, [projects]);
    useEffect(() => {
        localStorage.setItem('journalTracking', JSON.stringify(journals));
    }, [journals]);
    useEffect(() => {
        localStorage.setItem('tracking', tracking);
    }, [tracking]);

    // Search/filter journals by project description or goal text
    useEffect(() => {
        if (!newProjectDescription) return;
        const searchTerm = newProjectDescription.toLowerCase();
        const filteredJournals = journals.map(journalGroup => {
            let groupMatch = journalGroup.title?.toLowerCase().includes(searchTerm);
            let journalsMatch = false;
            if (journalGroup.journals) {
                journalsMatch = journalGroup.journals.some(journal =>
                    journal.description?.toLowerCase().includes(searchTerm) ||
                    journal.journal?.toLowerCase().includes(searchTerm) ||
                    journal.feelings?.toLowerCase().includes(searchTerm) ||
                    (journal.todaysGoals && journal.todaysGoals.some(goal => goal[0]?.toLowerCase().includes(searchTerm))) ||
                    (journal.futureGoals && journal.futureGoals.some(goal => goal[0]?.toLowerCase().includes(searchTerm))) ||
                    journal.gratefulFor?.toLowerCase().includes(searchTerm)
                );
            }
            return {
                ...journalGroup,
                display: groupMatch || journalsMatch || !searchTerm,
                journals: journalGroup.journals
                    ? journalGroup.journals.map(journal => ({
                        ...journal,
                        display: groupMatch || journalsMatch || !searchTerm
                    }))
                    : []
            };
        });
        setJournals(filteredJournals);
    }, [newProjectDescription]);

    // Add a new journal group/project
    const addProject = () => {
        if (!newProjectDescription.trim()) return;
        const newJournalGroup = {
            title: newProjectDescription,
            createdDate: currentDate(),
            startTime: currentTime(),
            tasks: [],
            journal: [],
            journals: [],
            totalTime: 0,
            isCollapsed: false
        };
        setJournals(prev => [...prev, newJournalGroup]);
        setNewProjectDescription('');
    };

    // Toggle goal completion
    const toggleCheckbox = (category, journalGroupIndex, journalIndex, goalIndex) => {
        setJournals(prev => {
            const updated = [...prev];
            const goal = updated[journalGroupIndex].journals[journalIndex][category][goalIndex];
            goal[1] = !goal[1];
            return updated;
        });
    };

    // Render goal lists
    const renderGoals = (type, collapseState, setCollapseState, filterFn) => (
        <div className='containerBox color-yellow'>
            <CollapseToggleButton
                title={type}
                isCollapsed={collapseState}
                setCollapse={setCollapseState}
                align='left'
            />
            {!collapseState &&
                <div className='containerBox'>
                    {journals && journals.length > 0 &&
                        journals.map((journalGroup, groupIdx) =>
                            journalGroup.journals && journalGroup.journals.length > 0 &&
                            journalGroup.journals.map((journal, journalIdx) =>
                                journal[type.toLowerCase().replace(' ', '')]?.map((goal, goalIdx) =>
                                    filterFn(goal) &&
                                    <div className='containerBox flexContainer centerVertical' key={getKey(`${type}${goal}${goalIdx}`)}>
                                        <div className='flex2Column contentLeft'>{goal[0]}</div>
                                        <div
                                            title='toggle checkbox'
                                            className='containerBox bg-lite p-20 button'
                                            onClick={() => toggleCheckbox(type.toLowerCase().replace(' ', ''), groupIdx, journalIdx, goalIdx)}
                                        >
                                            <input
                                                id='completed'
                                                name='completed'
                                                className='regular-checkbox'
                                                checked={goal[1]}
                                                type='checkbox'
                                                readOnly
                                            />
                                        </div>
                                    </div>
                                )
                            )
                        )
                    }
                </div>
            }
        </div>
    );

    return (
        <div className='mt--30'>
            <div className='pt-5'>
                <AddProjectInterface
                    newProjectDescription={newProjectDescription}
                    setNewProjectDescription={setNewProjectDescription}
                    addProject={addProject}
                    tracking={tracking}
                />
            </div>
            <div>
                {tracking === 'journals' &&
                    <div>
                        {renderGoals('todaysGoals', currentGoalsCollapse, setCurrentGoalsCollapse, goal => !goal[1])}
                        {renderGoals('futureGoals', futureGoalsCollapse, setFutureGoalsCollapse, goal => !goal[1])}
                        {renderGoals('todaysGoals', completedGoalsCollapse, setCompletedGoalsCollapse, goal => goal[1])}
                        {renderGoals('futureGoals', completedGoalsCollapse, setCompletedGoalsCollapse, goal => goal[1])}
                    </div>
                }
                {tracking === 'journals' &&
                    <TrackJournal
                        journals={journals}
                        setJournals={setJournals}
                        targetElementRef={targetElementRef}
                        scrollToBottom={() => targetElementRef.current?.scrollIntoView({ behavior: 'smooth', block: 'end' })}
                    />
                }
            </div>
        </div>
    );
};

export default Journals;